import glob
import logging
import re

from taf.collectors.core.entities.collector import CommonOamCollector, \
    CommonOamCUCollector, VduCollector
from taf.collectors.core.templates.dynamic_class_creation import Using

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class PmCounterCollectorBase(Using("local_executor")):

    def __init__(self,
                 pmsetup_filter=None,
                 **kwargs):
        super(PmCounterCollectorBase, self).__init__(**kwargs)
        self._pmsetup_filter = pmsetup_filter

    @staticmethod
    def get_absolute_target_path_of_pmfiles(target_dir):
        target_dir = re.sub(r"[\[|\]]", r"[\g<0>]", target_dir)
        return sorted(glob.glob(target_dir + '/*.xml') + glob.glob(target_dir + '/*.raw'))

    def apply_pmsetup_filter(self, target_dir):
        if self._pmsetup_filter:
            self._pmsetup_filter.remove_unwanted_files(target_dir)
            for pm_file in self.get_absolute_target_path_of_pmfiles(target_dir):
                self._pmsetup_filter.remove_unwanted_pmsetup_tags(pm_file)


class CoamPmCounterCollector(PmCounterCollectorBase, CommonOamCollector):
    """
    Create ADMIN API based collector.
    """

    def __init__(self,
                 timeout=120,
                 **kwargs):
        super(CoamPmCounterCollector, self).__init__(**kwargs)
        self._timeout = timeout

    def _collect(self, target_dir):
        """
        Transfer the information, that shall be collected, from the remote host to the local host.

        :param str target_dir: target path, where collected information shall be stored on the
        local host
        """
        if self._pmsetup_filter:
            self._pmsetup_filter.initialise_filter_criteria()
        get_pm_files = self._managed_admin_connection.get_pm_files(
            local_file_path="/tmp/coam_pmfiles.enc", timeout=self._timeout)
        logger.debug("get_pm_files=%r", get_pm_files)
        self._local_executor.execute(
            "base64 -d '{get_pm_files}' > /tmp/coam_pmfiles".format(
                get_pm_files=get_pm_files).encode())
        unzip_command = "unzip -j -o /tmp/coam_pmfiles"
        ignoring_specific_warning_message_from_stderr = "2> >(egrep -v \"stripped absolute path spec from\" >&2)"
        search_gzip_files = "find -type f -name \\*.gz"
        check_and_select_proper_gzip_files = "taf-file application/gzip"
        self._local_executor.execute(
            "cd '{target_dir}' ;"
            " {unzip_command} {ignoring_specific_warning_message_from_stderr} ;"
            " {search_gzip_files} | {check_and_select_proper_gzip_files}"
            " | xargs gunzip -f".format(
                target_dir=target_dir,
                unzip_command=unzip_command,
                ignoring_specific_warning_message_from_stderr=ignoring_specific_warning_message_from_stderr,
                search_gzip_files=search_gzip_files,
                check_and_select_proper_gzip_files=check_and_select_proper_gzip_files).encode())
        self.apply_pmsetup_filter(target_dir)
        self._local_executor.execute("rm -f /tmp/coam_pmfiles /tmp/coam_pmfiles.enc".encode())


class CoamVCUPmCounterCollector(PmCounterCollectorBase, CommonOamCUCollector, Using("file_getter")):
    """
    collection of a Coam CU PMCounters is triggered at the REST API and the result is stored locally in the directory
    target_dir, that is given to the copy all the collected pmcounters in to that .
    """

    def __init__(self, timeout=120, **kwargs):
        super(CoamVCUPmCounterCollector, self).__init__(**kwargs)
        self._timeout = timeout

    def _collect(self, target_dir):
        """
            Transfer the information, that shall be collected, from the remote host to the local host.

            :param str target_dir: target path, where collected information shall be stored on the local host
        """
        if self._pmsetup_filter:
            self._pmsetup_filter.initialise_filter_criteria()
        self._file_getter.get_file(self._cu_connection.get_all_raw_measurement_data(self._timeout), target_dir)
        self._local_executor.execute(
            "cd '{target_dir}' ; "
            "unzip -j -o *.zip ; "
            "chmod +rw *.gz ; "
            "gunzip -f *.gz".format(
                target_dir=target_dir).encode())
        self.apply_pmsetup_filter(target_dir)


